import{_ as o,a0 as u,w as l,s,I as n,x as d,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"開源電子郵件客户端 Thunderbird 即將登陸 Android | LCTT x X-CMD","titleTemplate":false,"description":"開源電子郵件客户端 Thunderbird 即將登陸 Android | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源電子郵件客户端 Thunderbird 即將登陸 Android | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源電子郵件客户端 Thunderbird 即將登陸 Android | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220614 Thunderbird, The Open Source Email Client, Is Coming To Android","title":"開源電子郵件客户端 Thunderbird 即將登陸 Android","tag":"202206","desc":""},"relativePath":"202206/20220614 Thunderbird, The Open Source Email Client, Is Coming To Android.md","filePath":"[post].md"}'),T={name:"202206/20220614 Thunderbird, The Open Source Email Client, Is Coming To Android.md"};function p(b,r,a,m,h,f){const e=u("Link");return l(),s("div",null,[r[15]||(r[15]=n("h1",{id:"開源電子郵件客户端-thunderbird-即將登陸-android",tabindex:"-1"},[d("開源電子郵件客户端 Thunderbird 即將登陸 Android "),n("a",{class:"header-anchor",href:"#開源電子郵件客户端-thunderbird-即將登陸-android","aria-label":"Permalink to “開源電子郵件客户端 Thunderbird 即將登陸 Android”"},"​")],-1)),r[16]||(r[16]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202206/16/084004gdzgp4bqgigi9tpe.jpg",alt:""})],-1)),r[17]||(r[17]=n("p",null,"開源電子郵件客户端 Thunderbird 將通過 K-9 Mail Android 電子郵件應用項目登陸 Android，該項目與 Thunderbird 合併後的產品就是 Thunderbird Android 電子郵件應用。兩年前，Thunderbird 被轉移到了 Mozilla 基金會的子公司 MZLA Technologies Corporation 下，該公司的所有權結構與基金會子公司 Mozilla 公司旗下的 Firefox 類似。有了 OpenPGP 端到端加密和期待已久的移動應用等新功能，Thunderbird 項目能夠開闢出一條自己的道路。",-1)),r[18]||(r[18]=n("p",null,"根據 Thunderbird 團隊的説法，Thunderbird 產品經理 Ryan Lee Sipes 和 K-9 的主要維護者 Christian Ketterer，兩人早在 2018 年就開始討論可能的 Thunderbird 電子郵件應用合作了。到了 2022 年，兩人決定不再讓 Thunderbird 從頭開始​​開發自己的應用程序，而是直接讓 K-9 加入 Thunderbird。",-1)),r[19]||(r[19]=n("p",null,"Thunderbird 團隊表示：“許多 Thunderbird 用户都要求在移動設備上獲得 Thunderbird 體驗，我們打算通過把 K-9 打造成令人驚歎的產品（並將其變成 Android 上的 Thunderbird）來提供這種體驗。K-9 將補充提供 Thunderbird 體驗，並增強它的使用場景和方式，讓用户獲得出色的電子郵件體驗。我們對桌面 Thunderbird 的承諾沒有改變，我們團隊中的大多數人都致力於將其打造為一流的電子郵件客户端，並將保持這種狀態。”",-1)),r[20]||(r[20]=n("p",null,"雖然 K-9 在 Google Play 上並不是特別受歡迎的電子郵件應用，但它已經獲得了 500 萬次下載。K-9 Mail 的路線圖目前包括：使用 Thunderbird 帳户自動配置的帳户設置、改進的文件夾管理、消息過濾器支持，以及桌面和移動 Thunderbird 之間的同步。雖然 Thunderbird 知道人們對 iOS 版 Thunderbird 應用程序也很感興趣，但在常見問題解答（FAQ）中，該項目僅聲明它正在“評估”這種可能性。",-1)),r[21]||(r[21]=n("p",null,"Thunderbird 團隊還打算將 Firefox Sync 作為一種在 Thunderbird 和 K-9 Mail 之間同步帳户的方法。它應該會在 2023 年夏天正式投入使用。該項目還在研究將哪些 Thunderbird 功能引入 Android 應用程序，例如日曆、任務、提要和聊天支持等。",-1)),r[22]||(r[22]=n("hr",null,null,-1)),n("p",null,[r[1]||(r[1]=d("via: ",-1)),i(e,{href:"https://www.opensourceforu.com/2022/06/thunderbird-the-open-source-email-client-is-coming-to-android/"},{default:t(()=>[...r[0]||(r[0]=[d("https://www.opensourceforu.com/2022/06/thunderbird-the-open-source-email-client-is-coming-to-android/",-1)])]),_:1})]),n("p",null,[r[6]||(r[6]=d("作者：",-1)),i(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:t(()=>[...r[2]||(r[2]=[d("Laveesh Kocher",-1)])]),_:1}),r[7]||(r[7]=d(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:t(()=>[...r[3]||(r[3]=[d("lkxed",-1)])]),_:1}),r[8]||(r[8]=d(" 譯者：",-1)),i(e,{href:"https://github.com/lkxed"},{default:t(()=>[...r[4]||(r[4]=[d("lkxed",-1)])]),_:1}),r[9]||(r[9]=d(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...r[5]||(r[5]=[d("wxy",-1)])]),_:1})]),n("p",null,[r[12]||(r[12]=d("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...r[10]||(r[10]=[d("LCTT",-1)])]),_:1}),r[13]||(r[13]=d(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...r[11]||(r[11]=[d("Linux中國",-1)])]),_:1}),r[14]||(r[14]=d(" 榮譽推出",-1))])])}const A=o(T,[["render",p]]);export{x as __pageData,A as default};
